# bash completion for kanbn
#
# Generated by `kanbn completion bash`. Load it from ~/.bashrc with:
#
#   eval "$(kanbn completion bash)"

# Give up rather than hang the shell if completion ever takes too long. timeout isn't on macOS by
# default, where it's gtimeout if coreutils is installed and nothing otherwise
if command -v timeout >/dev/null 2>&1; then
  _kanbn_timeout=timeout
elif command -v gtimeout >/dev/null 2>&1; then
  _kanbn_timeout=gtimeout
else
  _kanbn_timeout=
fi

_kanbn_completions() {
  local out line value
  local safe='^[A-Za-z0-9._@=+-]+$'
  COMPREPLY=()

  # Only the words up to and including the one being completed
  if [ -n "$_kanbn_timeout" ]; then
    out=$("$_kanbn_timeout" 0.25 kanbn __complete -- "${COMP_WORDS[@]:0:COMP_CWORD+1}" 2>/dev/null) || return 0
  else
    out=$(kanbn __complete -- "${COMP_WORDS[@]:0:COMP_CWORD+1}" 2>/dev/null) || return 0
  fi

  local IFS=$'\n'
  for line in $out; do
    case "$line" in
      :*) continue ;;
    esac
    value=${line%%$'\t'*}

    # Values that would need quoting (column names with spaces, mostly) are left out, rather than
    # being inserted in a form bash would then split. zsh and fish complete them properly
    if [[ $value =~ $safe ]]; then
      COMPREPLY+=("$value")
    fi
  done
  return 0
}

complete -F _kanbn_completions kanbn
